class MainActivity:ComponentActivity(){override fun onCreate(s:Bundle?){super.onCreate(s);val db=AppDatabase.create(this);setContent{InvoiceProTheme{val vm:AppVm=viewModel(factory=AppVm.factory(db)); InvoiceProApp(vm)}}}}
class AppVm(private val db:AppDatabase):ViewModel(){
 val invoices=db.invoiceDao().invoices().stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList()); val companies=db.companyDao().companies().stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList()); val active=db.companyDao().active().stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),null)
 fun saveCompany(c:CompanyEntity){viewModelScope.launch{if(c.id==0){val id=db.companyDao().insert(c);if(c.role=="SELLER"&&active.value==null) db.companyDao().activate(c.copy(id=id))}else db.companyDao().update(c)}}
 fun deleteCompany(c:CompanyEntity)=viewModelScope.launch{db.companyDao().delete(c)}; fun activate(c:CompanyEntity)=viewModelScope.launch{db.companyDao().activate(c)}
 fun items(companyId:Long)=db.itemDao().items(companyId).stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList()); fun saveItem(i:ItemEntity)=viewModelScope.launch{if(i.id==0)db.itemDao().insert(i)else db.itemDao().update(i)};fun deleteItem(i:ItemEntity)=viewModelScope.launch{db.itemDao().delete(i)}
 fun saveInvoice(number:String,seller:CompanyEntity,buyer:String,line:DraftLine,summary:TaxSummary){viewModelScope.launch{val invoice=InvoiceEntity(number=number,date=System.currentTimeMillis(),sellerId=seller.id,buyerId=null,sellerSnapshot=seller.name,buyerSnapshot=buyer,taxMode="INTRA_STATE",subtotal=summary.subtotal.toPlainString(),taxTotal=(summary.cgst+summary.sgst).toPlainString(),roundOff=summary.roundOff.toPlainString(),grandTotal=summary.grandTotal.toPlainString());db.invoiceDao().save(invoice,listOf(InvoiceItemEntity(invoiceId=0,sourceItemId=null,description=line.description,hsn=line.hsn,quantity=line.quantity.toPlainString(),unit=line.unit,rate=line.rate.toPlainString(),gst=line.gst.toPlainString(),taxable=summary.lines.first().taxable.toPlainString(),tax=summary.lines.first().tax.toPlainString(),total=summary.lines.first().total.toPlainString())))}}
 companion object{fun factory(db:AppDatabase)=object:ViewModelProvider.Factory{override fun <T:ViewModel> create(c:Class<T>):T{@Suppress("UNCHECKED_CAST")return AppVm(db)as T}}}
}
private val Ink=Color(0xFF111111); private val Paper=Color(0xFFF9F9F9); private val Line=Color(0xFFE5E7EB)
@Composable fun InvoiceProTheme(content:@Composable()->Unit){MaterialTheme(colorScheme=lightColorScheme(primary=Color.Black,onPrimary=Color.White,background=Paper,surface=Color.White,onSurface=Ink),content=content)}
@Composable fun InvoiceProApp(vm:AppVm){var tab by rememberSaveable{mutableStateOf(0)};var showCreate by rememberSaveable{mutableStateOf(false)};Scaffold(containerColor=Paper,bottomBar={NavigationBar(containerColor=Color.White,tonalElevation=0.dp){listOf("Home","Item",vm.active.collectAsStateWithLifecycle().value?.name?.take(8)?:"Company","Settings").forEachIndexed{i,t->NavigationBarItem(selected=tab==i,onClick={tab=i},icon={Text(listOf("⌂","□","▣","⚙")[i])},label={Text(t)})}}},floatingActionButton={if(tab<2)FloatingActionButton(containerColor=Ink,contentColor=Color.White,onClick={showCreate=true}){Text("+")}}){pad->Box(Modifier.padding(pad)){when(tab){0->Home(vm);1->Items(vm);2->Companies(vm);else->Settings(vm)};if(showCreate)InvoiceWizard(vm,{showCreate=false})}}}
@Composable fun Screen(title:String,body:@Composable ColumnScope.()->Unit){Column(Modifier.fillMaxSize().padding(16.dp)){Text("INVOICEPRO",style=MaterialTheme.typography.labelSmall,color=Color.Gray);Text(title,style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold);Spacer(Modifier.height(16.dp));body()}}
fun money(v:String)=NumberFormat.getCurrencyInstance(Locale("en","IN")).format(v.toBigDecimalOrNull()?:BigDecimal.ZERO)
@Composable fun Home(vm:AppVm){val invoices by vm.invoices.collectAsStateWithLifecycle();val seller by vm.active.collectAsStateWithLifecycle();Screen("Home"){Text("Good morning,",color=Color.Gray);Text(seller?.name?:"Set up your business",fontWeight=FontWeight.Bold);Spacer(Modifier.height(16.dp));val total=invoices.fold(BigDecimal.ZERO){a,b->a+(b.grandTotal.toBigDecimalOrNull()?:BigDecimal.ZERO)};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(10.dp)){Metric("INVOICES",invoices.size.toString(),Modifier.weight(1f));Metric("TOTAL SALES",money(total.toPlainString()),Modifier.weight(1f))};Spacer(Modifier.height(20.dp));Text("Recent invoices",fontWeight=FontWeight.SemiBold);if(invoices.isEmpty())Empty("No invoices yet. Tap + to create your first invoice.") else LazyColumn{items(invoices,key={it.id}){i->InvoiceRow(i)}}}}
@Composable fun Metric(label:String,value:String,modifier:Modifier){Column(modifier.border(1.dp,Line,RoundedCornerShape(8.dp)).padding(12.dp)){Text(label,style=MaterialTheme.typography.labelSmall,color=Color.Gray);Text(value,fontWeight=FontWeight.Bold)}}
@Composable fun InvoiceRow(i:InvoiceEntity){Row(Modifier.fillMaxWidth().padding(vertical=12.dp).border(1.dp,Line,RoundedCornerShape(8.dp)).padding(12.dp),horizontalArrangement=Arrangement.SpaceBetween){Column{Text(i.number,fontWeight=FontWeight.Bold);Text(Date(i.date).toString().take(11),style=MaterialTheme.typography.bodySmall,color=Color.Gray)};Text(money(i.grandTotal),fontWeight=FontWeight.Bold)}}
@Composable fun Empty(text:String){Box(Modifier.fillMaxWidth().padding(vertical=40.dp),contentAlignment=Alignment.Center){Text(text,color=Color.Gray)}}
@Composable fun Items(vm:AppVm){val company by vm.active.collectAsStateWithLifecycle();if(company==null){Screen("Item catalogue"){Empty("Add and select a seller company first.")};return};val items by vm.items(company!!.id).collectAsStateWithLifecycle();var add by remember{mutableStateOf(false)};Screen("Item catalogue"){Text("For ${company!!.name}",color=Color.Gray);Spacer(Modifier.height(12.dp));Button(onClick={add=true},modifier=Modifier.fillMaxWidth()){Text("Add item")};if(items.isEmpty())Empty("No saved products.") else LazyColumn{items(items,key={it.id}){item->Row(Modifier.fillMaxWidth().padding(vertical=10.dp).border(1.dp,Line,RoundedCornerShape(8.dp)).padding(12.dp),horizontalArrangement=Arrangement.SpaceBetween){Column{Text(item.name,fontWeight=FontWeight.Bold);Text("HSN ${item.hsn} · ${item.gst}% GST · ${item.unit}",style=MaterialTheme.typography.bodySmall,color=Color.Gray)};Text(money(item.rate))}}};if(add)ItemForm(company!!.id,{vm.saveItem(it);add=false},{add=false})}}
@Composable fun Companies(vm:AppVm){val list by vm.companies.collectAsStateWithLifecycle();var add by remember{mutableStateOf(false)};Screen("Company"){Button(onClick={add=true},modifier=Modifier.fillMaxWidth()){Text("Add company")};Spacer(Modifier.height(12.dp));if(list.isEmpty())Empty("Add a seller company to get started.")else LazyColumn{items(list,key={it.id}){c->Row(Modifier.fillMaxWidth().padding(vertical=8.dp).border(1.dp,Line,RoundedCornerShape(8.dp)).padding(12.dp).clickable{if(c.role=="SELLER")vm.activate(c)},horizontalArrangement=Arrangement.SpaceBetween){Column{Text(c.name,fontWeight=FontWeight.Bold);Text("${c.role} · ${c.gstin}",style=MaterialTheme.typography.bodySmall,color=Color.Gray)};if(c.isActiveSeller)Text("ACTIVE",style=MaterialTheme.typography.labelSmall,fontWeight=FontWeight.Bold)}}};if(add)CompanyForm({vm.saveCompany(it);add=false},{add=false})}}
@Composable fun Settings(vm:AppVm){Screen("Settings"){listOf("Companies","Invoice Settings","Tax Settings","Backup & Restore","Appearance","About").forEach{Text(it,Modifier.fillMaxWidth().padding(vertical=18.dp).border(width=0.dp,color=Color.Transparent),fontWeight=FontWeight.Medium);HorizontalDivider(color=Line)}}}
@Composable fun CompanyForm(save:(CompanyEntity)->Unit,cancel:()->Unit){var name by remember{mutableStateOf("")};var role by remember{mutableStateOf("SELLER")};var state by remember{mutableStateOf("")};var code by remember{mutableStateOf("")};var gst by remember{mutableStateOf("")};Dialog(onDismissRequest=cancel){Surface(shape=RoundedCornerShape(12.dp)){Column(Modifier.padding(20.dp)){Text("Add company",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold);Field("Company name",name){name=it};Field("State",state){state=it};Field("State code",code){code=it};Field("GSTIN/UIN",gst){gst=it};Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){FilterChip(selected=role=="SELLER",onClick={role="SELLER"},label={Text("Seller")});FilterChip(selected=role=="CUSTOMER",onClick={role="CUSTOMER"},label={Text("Customer")})};Spacer(Modifier.height(14.dp));Row(horizontalArrangement=Arrangement.End,modifier=Modifier.fillMaxWidth()){TextButton(onClick=cancel){Text("Cancel")};Button(onClick={if(name.isNotBlank())save(CompanyEntity(name=name,role=role,state=state,stateCode=code,gstin=gst))}){Text("Save")}}}}}}
@Composable fun ItemForm(companyId:Long,save:(ItemEntity)->Unit,cancel:()->Unit){var name by remember{mutableStateOf("")};var hsn by remember{mutableStateOf("")};var rate by remember{mutableStateOf("")};var gst by remember{mutableStateOf("18")};var unit by remember{mutableStateOf("Nos")};Dialog(onDismissRequest=cancel){Surface(shape=RoundedCornerShape(12.dp)){Column(Modifier.padding(20.dp)){Text("Add item",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold);Field("Item name",name){name=it};Field("HSN/SAC",hsn){hsn=it};Field("Selling rate",rate,KeyboardType.Decimal){rate=it};Field("GST percentage",gst,KeyboardType.Decimal){gst=it};Field("Unit",unit){unit=it};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.End){TextButton(onClick=cancel){Text("Cancel")};Button(onClick={if(name.isNotBlank()&&rate.toBigDecimalOrNull()!=null)save(ItemEntity(companyId=companyId,name=name,hsn=hsn,rate=rate,gst=gst,unit=unit))}){Text("Save item")}}}}}}
@Composable fun Field(label:String,value:String,type:KeyboardType=KeyboardType.Text,onChange:(String)->Unit){OutlinedTextField(value=value,onValueChange=onChange,label={Text(label)},keyboardOptions=androidx.compose.foundation.text.KeyboardOptions(keyboardType=type),singleLine=true,modifier=Modifier.fillMaxWidth().padding(top=8.dp))}
@Composable fun InvoiceWizard(vm:AppVm,dismiss:()->Unit){val all by vm.companies.collectAsStateWithLifecycle();val seller=all.firstOrNull{it.isActiveSeller};var stage by rememberSaveable{mutableStateOf(0)};var buyer by rememberSaveable{mutableStateOf("")};var number by rememberSaveable{mutableStateOf("GST/${Calendar.getInstance().get(Calendar.YEAR)}/001")};var description by rememberSaveable{mutableStateOf("")};var rate by rememberSaveable{mutableStateOf("")};var qty by rememberSaveable{mutableStateOf("1")};var gst by rememberSaveable{mutableStateOf("18")};val line=remember(description,rate,qty,gst){if(rate.toBigDecimalOrNull()!=null&&qty.toBigDecimalOrNull()!=null)DraftLine(description.ifBlank{"Manual item"},"",qty.toBigDecimal(),rate.toBigDecimal(),gst.toBigDecimalOrNull()?:BigDecimal.ZERO)else null};val summary=line?.let{GstCalculator.calculate(listOf(it),false)};Dialog(onDismissRequest=dismiss){Surface(Modifier.fillMaxWidth().padding(12.dp),shape=RoundedCornerShape(12.dp)){Column(Modifier.padding(20.dp)){Text("Create invoice",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Text("Stage ${stage+1} of 3 · Details / Items / Review",color=Color.Gray);when(stage){0->{Field("Invoice number",number){number=it};Field("Buyer / customer name",buyer){buyer=it};Text("Seller: ${seller?.name?:"No active seller"}")};1->{Field("Description",description){description=it};Field("Quantity",qty,KeyboardType.Decimal){qty=it};Field("Rate",rate,KeyboardType.Decimal){rate=it};Field("GST %",gst,KeyboardType.Decimal){gst=it};Text("Subtotal: ${summary?.let{money(it.subtotal.toPlainString())}?:"₹0.00"}")};else->{Text("${seller?.name?:"Seller required"} → ${buyer.ifBlank{"Customer required"}",fontWeight=FontWeight.Bold);Text(description.ifBlank{"No item"});Text("Grand total: ${summary?.let{money(it.grandTotal.toPlainString())}?:"₹0.00"}",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold)}};Spacer(Modifier.height(16.dp));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){TextButton(onClick={if(stage==0)dismiss()else stage--}){Text(if(stage==0)"Cancel" else "Back")};Button(onClick={if(stage<2)stage++ else {vm.saveInvoice(number,seller!!,buyer,line!!,summary!!);dismiss()}},enabled=stage!=2||(seller!=null&&summary!=null)){Text(if(stage<2)"Next" else "Save invoice")}}}}}}
